describe("sympy/strategies/tests/test_tree.py", () => {
  it("test_treeapply:32", () => {
    expect(sympyStr(mul(add(Rational.of(3n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n })), add(Rational.of(4n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })), Rational.of(2n, 1n, { gcd: 1n })))).toBe('60');
  });
  it("test_treeapply_leaf:36", () => {
    expect(sympyStr(Lambda([new Dummy('x', {}, 1000000)], new Pow(new Dummy('x', {}, 1000000), Rational.of(2n, 1n, { gcd: 1n }))).call(Rational.of(3n, 1n, { gcd: 1n })))).toBe('9');
  });
});
